fn solve(n_a: i8, n_b: i8, k: i8, m: i8, a: Vec<i8>, b: Vec<i8>) -> &'static str {
    // Convert 1-based indices to 0-based
    let idx_a = (k as usize) - 1;
    // m-th from end in b is at index b.len() - m (0-based)
    let idx_b = b.len() - (m as usize);

    if a[idx_a] < b[idx_b] {
        "YES"
    } else {
        "NO"
    }
}

